//! Every official catalog head and tail as one clean path, for drawing snakes
//! server-side (social cards). A static table, so nothing is processed at runtime.
//!
//! Generated by processing the catalog SVGs vendored in
//! `server/tests/fixtures/design_kit/catalog/` with [`super::process_upload`], the same
//! pipeline an artist's upload takes: a multi-colour asset becomes one colour with its
//! near-white details (eyes, teeth) cut out. `server/tests/design_kit_catalog.rs` checks
//! every entry against fresh output while it checks the corpus. To regenerate after a
//! pipeline change or a new catalog asset:
//!
//! ```text
//! cargo test -p arena --test design_kit_catalog -- --ignored write_catalog_shapes
//! ```
//!
//! Keyed by media file, not slug: a catalog entry's art is `heads/{file}.svg` or
//! `tails/{file}.svg`, which is its slug except for the few entries that reuse another
//! entry's art (see `Head::image_url`).

use super::{AssetKind, FillRule};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CatalogShape {
    pub kind: AssetKind,
    /// The media file's name without `.svg`.
    pub file: &'static str,
    /// Absolute `M`/`L`/`Q`/`C`/`Z` commands in the 100x100 box, like `CleanShape::path_d`.
    pub d: &'static str,
    pub fill_rule: FillRule,
}

